# --- 4. 初始化 Session State ---
if 'index' not in st.session_state:
    st.session_state.index = 0
if 'show_answer' not in st.session_state:
    st.session_state.show_answer = False
if 'play_word_audio' not in st.session_state:
    st.session_state.play_word_audio = True
if 'play_sentence_audio' not in st.session_state:
    st.session_state.play_sentence_audio = True

# --- 5. 語音生成函數 ---
def get_audio_bytes(text):
    try:
        tts = gTTS(text=text, lang='en')
        fp = BytesIO()
        tts.write_to_fp(fp)
        fp.seek(0)
        return fp.read()
    except Exception:
        return None

# --- 6. 介面佈局 ---
max_len = len(verb_db)
current_val = min(st.session_state.index + 1, max_len)

# 頂部控制區：跳轉與朗讀開關設定列
col_s1, col_s2, col_s3, col_s4 = st.columns([1.5, 1, 1.2, 1.2])
with col_s1:
    start_input = st.number_input("跳至編號：", min_value=1, max_value=max_len, value=current_val)
with col_s2:
    st.markdown("<div style='height: 24px;'></div>", unsafe_allow_html=True)
    if st.button("跳轉"):
        st.session_state.index = int(start_input) - 1
        st.session_state.show_answer = False
        st.rerun()
with col_s3:
    st.session_state.play_word_audio = st.checkbox("朗讀單字", value=st.session_state.play_word_audio)
with col_s4:
    st.session_state.play_sentence_audio = st.checkbox("朗讀例句", value=st.session_state.play_sentence_audio)

st.markdown("---")

current_data = verb_db[st.session_state.index]
no, word, pos, mean, sen_en, sen_zh = current_data

# 進度顯示
st.markdown(f'<div class="progress-text">進度：{no} / {max_len} 筆</div>', unsafe_allow_html=True)

# 英文單字顯示
st.markdown(f'<div class="main-word">{word}</div>', unsafe_allow_html=True)

# 語音播放條與單字間距（根據設定決定是否朗讀單字）
st.markdown('<div class="audio-spacing"></div>', unsafe_allow_html=True)
if st.session_state.play_word_audio:
    audio_bytes = get_audio_bytes(word)
    if audio_bytes:
        st.audio(audio_bytes, format='audio/mp3', autoplay=True)

# 答案內容
if st.session_state.show_answer:
    st.markdown(f'<div class="pos-text">{pos}</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="mean-text">{mean}</div>', unsafe_allow_html=True)
    st.markdown(f"""
        <div class="sentence-box">
            <b>例句：</b>{sen_en}<br>
            <b>翻譯：</b>{sen_zh}
        </div>
    """, unsafe_allow_html=True)
    
    # 根據設定決定是否朗讀例句
    if st.session_state.play_sentence_audio:
        sen_audio_bytes = get_audio_bytes(sen_en)
        if sen_audio_bytes:
            st.audio(sen_audio_bytes, format='audio/mp3', autoplay=True)

st.markdown("---")

# 底部按鍵
if not st.session_state.show_answer:
    col_empty1, col_center, col_empty2 = st.columns([1, 4, 1])
    with col_center:
        if st.button("👁️ 顯示答案", type="primary"):
            st.session_state.show_answer = True
            st.rerun()
else:
    col_empty1, col_center, col_empty2 = st.columns([1, 4, 1])
    with col_center:
        if st.button("➡️ 下一題", type="primary"):
            if st.session_state.index < max_len - 1:
                st.session_state.index += 1
                st.session_state.show_answer = False
                st.rerun()
            else:
                st.success("🎉 複習完畢！")
